/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
const dir = await mkdtemp(join(tmpdir(), 'workboard-start-'));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '0', DB_PATH: join(dir, 'app.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  const port = await new Promise((resolve, reject) => {
    let output = '';
    const timer = setTimeout(() => reject(new Error('Start timed out')), 10000);
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/Workboard listening on port (\\d+)/);
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
    child.on('error', reject);
    child.on('exit', code => { clearTimeout(timer); reject(new Error('Server exited: ' + code)); });
  });
  const response = await fetch('http://127.0.0.1:' + port + '/health');
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: 'ok' });
  console.log('npm start and GET /health: passed');
} finally {
  process.kill(-child.pid, 'SIGTERM');
  await new Promise(resolve => child.once('exit', resolve));
  await rm(dir, { recursive: true, force: true });
}
JS"

